{"id": "test:1501", "question_original_en": "What is the last name of the customers who shopped at the bakery more than 10 times?", "question": "Quel est le nom de famille des clients qui ont fait leurs achats à la boulangerie plus de 10 fois ?", "sql": "SELECT T2.LastName FROM receipts AS T1 JOIN customers AS T2 ON T1.CustomerId  =  T2.id GROUP BY T2.id HAVING count(*)  >  10", "schema": "CREATE TABLE "customers" (
	"Id" INTEGER PRIMARY KEY,
	"LastName" TEXT,
	"FirstName" TEXT
);

CREATE TABLE "goods" (
	"Id" TEXT PRIMARY KEY,
	"Flavor" TEXT,
